# Вхід користувачів через BankID NBU

Ось повний код для реалізації входу користувачів через BankID NBU в Ruby:

## Gemfile
```ruby
source 'https://rubygems.org'

gem 'sinatra', '~> 3.0'
gem 'sinatra-contrib', '~> 3.0'
gem 'httparty', '~> 0.18'
gem 'json', '~> 2.6'
gem 'jwt', '~> 2.2'
gem 'openssl', '~> 3.0'
gem 'rack', '~> 2.2'
gem 'rack-session', '~> 1.0'
gem 'securerandom', '~> 0.1'
```

## app.rb
```ruby
require 'sinatra'
require 'sinatra/config_file'
require 'httparty'
require 'json'
require 'jwt'
require 'openssl'
require 'securerandom'
require 'rack/session'
require 'logger'

# Налаштування логування
set :logger, Logger.new(STDOUT)
set :logging, true

# Налаштування сесій
use Rack::Session::Cookie, 
    key: 'bankid_session',
    secret: ENV['SESSION_SECRET'] || 'your_secret_key_here'

# Конфігурація BankID
configure do
  set :bankid_url, ENV['BANKID_URL'] || 'https://api.bankid.gov.ua'
  set :bankid_client_id, ENV['BANKID_CLIENT_ID'] || 'your_client_id'
  set :bankid_client_secret, ENV['BANKID_CLIENT_SECRET'] || 'your_client_secret'
  set :bankid_redirect_uri, ENV['BANKID_REDIRECT_URI'] || 'http://localhost:4567/callback'
end

# Головна сторінка
get '/' do
  erb :index
end

# Сторінка входу через BankID
get '/login' do
  # Створення стану для безпеки
  state = SecureRandom.hex(16)
  session[:state] = state

  # Формування URL для авторизації
  bankid_auth_url = "#{settings.bankid_url}/oauth/authorize?" \
    "response_type=code&" \
    "client_id=#{settings.bankid_client_id}&" \
    "redirect_uri=#{settings.bankid_redirect_uri}&" \
    "state=#{state}"

  redirect bankid_auth_url
end

# Callback від BankID
get '/callback' do
  # Перевірка стану для захисту від CSRF
  if params[:state] != session[:state]
    halt 400, "Недійсний стан"
  end

  # Отримання коду авторизації
  if params[:code].nil?
    halt 400, "Відсутній код авторизації"
  end

  # Обмін коду на токен
  token_response = exchange_code_for_token(params[:code])

  if token_response[:error]
    halt 400, "Помилка отримання токена: #{token_response[:error]}"
  end

  # Отримання даних користувача
  user_data = get_user_info(token_response[:access_token])

  if user_data[:error]
    halt 400, "Помилка отримання даних користувача: #{user_data[:error]}"
  end

  # Збереження інформації про користувача у сесії
  session[:user] = {
    id: user_data[:user_id],
    name: user_data[:name],
    email: user_data[:email],
    phone: user_data[:phone],
    access_token: token_response[:access_token],
    refresh_token: token_response[:refresh_token]
  }

  # Перенаправлення на головну сторінку
  redirect '/profile'
end

# Профіль користувача
get '/profile' do
  if session[:user].nil?
    redirect '/login'
  end

  erb :profile, locals: { user: session[:user] }
end

# Вихід
get '/logout' do
  session.clear
  redirect '/'
end

# Обмін коду на токен
def exchange_code_for_token(code)
  url = "#{settings.bankid_url}/oauth/token"

  response = HTTParty.post(url, {
    headers: {
      'Content-Type' => 'application/x-www-form-urlencoded',
      'Accept' => 'application/json'
    },
    body: {
      grant_type: 'authorization_code',
      client_id: settings.bankid_client_id,
      client_secret: settings.bankid_client_secret,
      redirect_uri: settings.bankid_redirect_uri,
      code: code
    }
  })

  begin
    JSON.parse(response.body)
  rescue JSON::ParserError
    { error: "Неправильна відповідь від сервера" }
  end
end

# Отримання даних користувача
def get_user_info(access_token)
  url = "#{settings.bankid_url}/api/user/profile"

  response = HTTParty.get(url, {
    headers: {
      'Authorization' => "Bearer #{access_token}",
      'Accept' => 'application/json'
    }
  })

  begin
    data = JSON.parse(response.body)
    {
      user_id: data['id'],
      name: data['name'],
      email: data['email'],
      phone: data['phone']
    }
  rescue JSON::ParserError
    { error: "Неправильна відповідь від сервера" }
  rescue KeyError => e
    { error: "Відсутні необхідні поля: #{e.message}" }
  end
end

# Обробка помилок
error 400 do
  erb :error, locals: { message: "Помилка: #{request.env['sinatra.error'].message}" }
end

error 404 do
  erb :error, locals: { message: "Сторінку не знайдено" }
end

# Сторінка помилки
get '/error' do
  erb :error, locals: { message: params[:message] || "Сталася помилка" }
end
```

