end
```

## app.rb (основний додаток)

```ruby
require 'sinatra'
require 'sinatra/reloader' if development?
require 'httparty'
require 'json'

class PrivatBankCurrencyApp < Sinatra::Base
  configure :development do
    register Sinatra::Reloader
  end

  PRIVATBANK_API_URL = 'https://api.privatbank.ua/p24api/pubinfo?exchange&json&coursid=11'

  # Головна сторінка з курсами валют
  get '/' do
    @currencies = fetch_currency_rates
    erb :index
  end

  # API endpoint для отримання курсів в JSON форматі
  get '/api/rates' do
    content_type :json
    fetch_currency_rates.to_json
  end

  private

  def fetch_currency_rates
    begin
      response = HTTParty.get(PRIVATBANK_API_URL, timeout: 10)

      if response.success?
        parse_rates(response.body)
      else
        # Повертаємо порожній масив у разі помилки
        []
      end
    rescue => e
      # Логування помилки
      puts "Error fetching currency rates: #{e.message}"
      []
    end
  end

  def parse_rates(json_data)
    rates = JSON.parse(json_data)

    # Фільтруємо та форматуємо дані
    rates.map do |rate|
      {
        'ccy' => rate['ccy'],
        'base_ccy' => rate['base_ccy'],
        'buy' => rate['buy'].to_f,
        'sale' => rate['sale'].to_f
      }
    end
  rescue JSON::ParserError => e
    puts "Error parsing JSON: #{e.message}"
    []
  end
end
```

