### Файл: `services/nova_poshta_service.rb`

```ruby
class NovaPoshtaService
  include HTTParty
  base_uri NOVA_POSHTA_API_URL

  def initialize
    @headers = { 'Content-Type' => 'application/json' }
  end

  # Отримання координат за адресою
  def geocode_address(address)
    results = Geocoder.search(address)

    if results.any?
      {
        latitude: results.first.latitude,
        longitude: results.first.longitude,
        formatted_address: results.first.address
      }
    else
      raise "Не вдалося знайти координати для адреси: #{address}"
    end
  end

  # Пошук поштоматів поблизу заданих координат
  def find_post_boxes_nearby(latitude, longitude, radius_km = 2)
    # Конвертуємо кілометри в градуси (приблизно)
    lat_delta = radius_km / 111.0
    lon_delta = radius_km / (111.0 * Math.cos(latitude * Math::PI / 180.0))

    # Формуємо запит до API Nova Poshta
    request_body = {
      apiKey: NOVA_POSHTA_API_KEY,
      modelName: 'AddressGeneral',
      calledMethod: 'getPostBoxes',
      methodProperties: {
        lat1: latitude - lat_delta,
        lon1: longitude - lon_delta,
        lat2: latitude + lat_delta,
        lon2: longitude + lon_delta,
        limit: 50
      }
    }

    response = self.class.post('/AddressGeneral/getPostBoxes', 
                               headers: @headers, 
                               body: request_body.to_json)

    if response.success?
      data = JSON.parse(response.body)

      if data['success']
        post_boxes = data['data'] || []

        # Фільтруємо та форматуємо результати
        post_boxes.map do |box|
          {
            id: box['Ref'],
            city: box['CityDescription'],
            address: box['Address'],
            latitude: box['Latitude'].to_f,
            longitude: box['Longitude'].to_f,
            type: box['TypePostBoxDescription'],
            distance_km: calculate_distance(latitude, longitude, 
                                           box['Latitude'].to_f, 
                                           box['Longitude'].to_f)
          }
        end.sort_by { |box| box[:distance_km] }
      else
        raise "API помилка: #{data['errors']}"
      end
    else
      raise "HTTP помилка: #{response.code}"
    end
  end

  private

  # Розрахунок відстані між двома точками (формула гаверсинуса)
  def calculate_distance(lat1, lon1, lat2, lon2)
    earth_radius_km = 6371.0

    lat1_rad = lat1 * Math::PI / 180.0
    lat2_rad = lat2 * Math::PI / 180.0
    lon1_rad = lon1 * Math::PI / 180.0
    lon2_rad = lon2 * Math::PI / 180.0

    dlat = lat2_rad - lat1_rad
    dlon = lon2_rad - lon1_rad

    a = Math.sin(dlat/2)**2 + Math.cos(lat1_rad) * Math.cos(lat2_rad) * Math.sin(dlon/2)**2
    c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))

    (earth_radius_km * c).round(2)
  end
end
```

### Файл: `app.rb`

```ruby
require_relative 'config/environment'
require_relative 'services/nova_poshta_service'

class NovaPoshtaApp < Sinatra::Base
  configure :development do
    register Sinatra::Reloader
  end

  set :public_folder, File.dirname(__FILE__) + '/public'
  set :views, File.dirname(__FILE__) + '/views'

  # Головна сторінка
  get '/' do
    erb :index
  end

  # API endpoint для пошуку поштоматів
  post '/api/find_post_boxes' do
    content_type :json

    begin
      address = params[:address]
      radius = params[:radius].to_f || 2.0

      if address.nil? || address.empty?
        return { error: "Будь ласка, введіть адресу" }.to_json
      end

      service = NovaPoshtaService.new

      # Геокодуємо адресу
      coordinates = service.geocode_address(address)

      # Знаходимо поштомати
      post_boxes = service.find_post_boxes_nearby(
        coordinates[:latitude], 
        coordinates[:longitude], 
        radius
      )

      {
        success: true,
        center: coordinates,
        post_boxes: post_boxes,
        total: post_boxes.length
      }.to_json

    rescue StandardError => e
      status 500
      { error: e.message }.to_json
    end
  end
end

# Запускаємо додаток
NovaPoshtaApp.run! if __FILE__ == $0
```

