  content_type :json

  # Перевірка вхідних даних
  params = JSON.parse(request.body.read)

  unless params['amount'] && params['description']
    return { error: 'Missing required parameters: amount and description' }.to_json
  end

  # Створення замовлення в БД
  DB.execute(
    "INSERT INTO orders (amount, description) VALUES (?, ?)",
    [params['amount'], params['description']]
  )

  order_id = DB.last_insert_row_id

  # Повертаємо інформацію про замовлення
  {
    order_id: order_id,
    amount: params['amount'],
    description: params['description'],
    status: 'created'
  }.to_json
