# Створення оплати частинами
post '/orders/:order_id/payments' do
  content_type :json
  order_id = params[:order_id]

  # Перевірка існування замовлення
  order = DB.execute("SELECT * FROM orders WHERE id = ?", [order_id]).first
  if order.nil?
    return { error: 'Order not found' }.to_json
  end

  # Перевірка вхідних даних
  params = JSON.parse(request.body.read)

  unless params['amount'] && params['payment_method']
    return { error: 'Missing required parameters: amount and payment_method' }.to_json
  end

  # Перевірка, чи сума не перевищує суму замовлення
  if params['amount'] > order['amount']
    return { error: 'Payment amount exceeds order amount' }.to_json
  end

  # Створення оплати в БД
  DB.execute(
    "INSERT INTO payments (order_id, amount, payment_method) VALUES (?, ?, ?)",
    [order_id, params['amount'], params['payment_method']]
  )

  payment_id = DB.last_insert_row_id

  # Симуляція інтеграції з ПриватБанком
  payment_result = process_payment_with_privatbank(order_id, payment_id, params['amount'])

  # Оновлення статусу оплати
  status = payment_result['status'] == 'success' ? 'completed' : 'failed'
  DB.execute("UPDATE payments SET status = ? WHERE id = ?", [status, payment_id])

  # Повертаємо результат
  {
    payment_id: payment_id,
    order_id: order_id,
    amount: params['amount'],
    payment_method: params['payment_method'],
    status: status,
    transaction_id: payment_result['transaction_id']
  }.to_json
end

