    </form>

    <div id="orderResult" class="result" style="display: none;"></div>

    <h2>Оплата частинами</h2>
    <form id="paymentForm">
      <div class="form-group">
        <label for="order_id">ID замовлення:</label>
        <input type="number" id="order_id" name="order_id" required>
      </div>

