        <label for="details_order_id">ID замовлення:</label>
        <input type="number" id="details_order_id" name="order_id" required>
      </div>

      <button type="submit">Отримати деталі</button>
    </form>

    <div id="detailsResult" class="result" style="display: none;"></div>
  </div>

  <script>
    document.getElementById('createOrderForm').addEventListener('submit', function(e) {
      e.preventDefault();

      const formData = new FormData(this);
      const data = Object.fromEntries(formData);

      fetch('/orders', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data)
      })
      .then(response => response.json())
      .then(result => {
        const resultDiv = document.getElementById('orderResult');
        if (result.error) {
          resultDiv.className = 'result error';
          resultDiv.innerHTML = `<h3>Помилка:</h3><p>${result.error}</p>`;
        } else {
          resultDiv.className = 'result';
          resultDiv.innerHTML = `<h3>Успішно створено:</h3><p>ID замовлення: ${result.order_id}</p><p>Сума: ${result.amount} UAH</p><p>Опис: ${result.description}</p>`;
        }
        resultDiv.style.display = 'block';
      })
      .catch(error => {
        const resultDiv = document.getElementById('orderResult');
        resultDiv.className = 'result error';
        resultDiv.innerHTML = `<h3>Помилка:</h3><p>${error.message}</p>`;
        resultDiv.style.display = 'block';
      });
    });

    document.getElementById('paymentForm').addEventListener('submit', function(e) {
      e.preventDefault();

      const formData = new FormData(this);
      const data = Object.fromEntries(formData);

      fetch(`/orders/${data.order_id}/payments`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          amount: parseFloat(data.amount),
          payment_method: data.payment_method
        })
      })
      .then(response => response.json())
      .then(result => {
        const resultDiv = document.getElementById('paymentResult');
        if (result.error) {
          resultDiv.className = 'result error';
          resultDiv.innerHTML = `<h3>Помилка:</h3><p>${result.error}</p>`;
        } else {
          resultDiv.className = 'result';
          resultDiv.innerHTML = `<h3>Успішна оплата:</h3><p>ID оплати: ${result.payment_id}</p><p>Статус: ${result.status}</p><p>ID транзакції: ${result.transaction_id}</p>`;
        }
        resultDiv.style.display = 'block';
      })
      .catch(error => {
        const resultDiv = document.getElementById('paymentResult');
        resultDiv.className = 'result error';
        resultDiv.innerHTML = `<h3>Помилка:</h3><p>${error.message}</p>`;
        resultDiv.style.display = 'block';
      });
    });

    document.getElementById('orderDetailsForm').addEventListener('submit', function(e) {
      e.preventDefault();

      const formData = new FormData(this);
      const orderId = formData.get('order_id');

      fetch(`/orders/${orderId}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        }
      })
      .then(response => response.json())
      .then(result => {
        const resultDiv = document.getElementById('detailsResult');
        if (result.error) {
          resultDiv.className = 'result error';
          resultDiv.innerHTML = `<h3>Помилка:</h3><p>${result.error}</p>`;
        } else {
          let paymentsHtml = '';
          result.payments.forEach(payment => {
            paymentsHtml += `
              <div>
                <strong>Оплата #${payment.payment_id}</strong><br>
                Сума: ${payment.amount} UAH<br>
                Статус: ${payment.status}<br>
                Спосіб: ${payment.payment_method}<br>
                Дата: ${payment.created_at}<br><br>
              </div>
            `;
          });

          resultDiv.className = 'result';
          resultDiv.innerHTML = `
            <h3>Деталі замовлення:</h3>
            <p>ID: ${result.order_id}</p>
            <p>Сума: ${result.amount} UAH</p>
            <p>Опис: ${result.description}</p>
            <p>Створено: ${result.created_at}</p>
            <h4>Оплати:</h4>
            ${paymentsHtml || '<p>Немає оплат</p>'}
          `;
        }
        resultDiv.style.display = 'block';
      })
      .catch(error => {
        const resultDiv = document.getElementById('detailsResult');
        resultDiv.className = 'result error';
        resultDiv.innerHTML = `<h3>Помилка:</h3><p>${error.message}</p>`;
        resultDiv.style.display = 'block';
      });
    });
  </script>
</body>
</html>
