## Основна програма (app.rb)

```ruby
require 'sinatra'
require 'httparty'
require 'json'

class CurrencyApp < Sinatra::Base
  # Головна сторінка з курсами валют
  get '/' do
    @currencies = fetch_currency_rates
    erb :index
  end

  # JSON API endpoint для отримання курсів
  get '/api/rates' do
    content_type :json
    fetch_currency_rates.to_json
  end

  private

  def fetch_currency_rates
    begin
      response = HTTParty.get(
        'https://api.privatbank.ua/p24api/pubinfo?exchange&json&coursid=11',
        timeout: 10
      )

      if response.success?
        JSON.parse(response.body)
      else
        { error: "Помилка отримання даних: #{response.code}" }
      end
    rescue StandardError => e
      { error: "Помилка: #{e.message}" }
    end
  end
end

# Запуск сервера
if __FILE__ == $0
  CurrencyApp.run!(port: 4567, bind: '0.0.0.0')
end
```

