## app.rb

```ruby
require 'sinatra'
require 'httparty'
require 'json'

class PrivatBankCurrencyApp < Sinatra::Base
  API_URL = 'https://api.privatbank.ua/p24api/pubinfo?exchange&coursid=5'

  configure do
    set :server, :puma
    set :port, 4567
  end

  def fetch_currency_rates
    response = HTTParty.get(API_URL)

    if response.success?
      JSON.parse(response.body)
    else
      []
    end
  rescue StandardError => e
    puts "Error fetching currency rates: #{e.message}"
    []
  end

  get '/' do
    @currencies = fetch_currency_rates
    @last_updated = Time.now.strftime("%Y-%m-%d %H:%M:%S")
    erb :index
  end

  get '/api/currencies' do
    content_type :json
    fetch_currency_rates.to_json
  end

  # Start the server if this file is run directly
  run! if app_file == $0
end
```

