## Основна програма

```ruby
# nova_poshta_map.rb
require 'sinatra'
require 'geocoder'
require 'httparty'
require 'json'

class NovaPoshtaMapper
  NOVA_POSHTA_API_URL = 'https://api.novaposhta.ua/v2.0/json/'

  def initialize(api_key)
    @api_key = api_key
  end

  def find_postomaty_near_address(address, radius_km = 5)
    # Геокодування адреси
    coordinates = geocode_address(address)
    return { error: 'Не вдалося знайти координати для вказаної адреси' } unless coordinates

    # Отримання поштоматів з API Nova Poshta
    postomaty = get_postomaty(coordinates, radius_km)

    { coordinates: coordinates, postomaty: postomaty }
  end

  private

  def geocode_address(address)
    results = Geocoder.search(address)
    return nil if results.empty?

    location = results.first
    { 
      lat: location.latitude, 
      lng: location.longitude,
      address: location.address
    }
  end

  def get_postomaty(coordinates, radius_km)
    request_body = {
      apiKey: @api_key,
      modelName: "AddressGeneral",
      calledMethod: "getWarehouses",
      methodProperties: {
        CityName: "", # Можна вказати місто для фільтрації
        Limit: 50
      }
    }

    response = HTTParty.post(
      NOVA_POSHTA_API_URL,
      body: request_body.to_json,
      headers: { 'Content-Type' => 'application/json' }
    )

    return [] unless response.success?

    warehouses = JSON.parse(response.body)['data'] || []

    # Фільтруємо поштомати за відстанню
    warehouses.select do |warehouse|
      warehouse_lat = warehouse['Latitude'].to_f
      warehouse_lng = warehouse['Longitude'].to_f

      distance = calculate_distance(
        coordinates[:lat], coordinates[:lng],
        warehouse_lat, warehouse_lng
      )

      distance <= radius_km
    end.map do |warehouse|
      {
        number: warehouse['Number'],
        name: warehouse['ShortAddress'],
        address: warehouse['ShortAddressRu'] || warehouse['ShortAddress'],
        lat: warehouse['Latitude'].to_f,
        lng: warehouse['Longitude'].to_f,
        schedule: warehouse['Schedule'],
        phone: warehouse['Phone']
      }
    end
  end

  def calculate_distance(lat1, lng1, lat2, lng2)
    # Формула гаверсинус для розрахунку відстані між двома точками
    rad_per_deg = Math::PI / 180
    earth_radius_km = 6371

    dlat_rad = (lat2 - lat1) * rad_per_deg
    dlng_rad = (lng2 - lng1) * rad_per_deg

    lat1_rad = lat1 * rad_per_deg
    lat2_rad = lat2 * rad_per_deg

    a = Math.sin(dlat_rad/2)**2 + Math.cos(lat1_rad) * Math.cos(lat2_rad) * Math.sin(dlng_rad/2)**2
    c = 2 * Math.asin(Math.sqrt(a))

    earth_radius_km * c
  end
end

# Веб-інтерфейс
class NovaPoshtaMapApp < Sinatra::Base
  set :public_folder, File.dirname(__FILE__) + '/public'

  API_KEY = ENV['NOVA_POSHTA_API_KEY'] || 'your_api_key_here'

  get '/' do
    erb :index
  end

  post '/find-postomaty' do
    content_type :json

    address = params[:address]
    radius = params[:radius]&.to_f || 5

    mapper = NovaPoshtaMapper.new(API_KEY)
    result = mapper.find_postomaty_near_address(address, radius)

    result.to_json
  end
end

# Запуск сервера
if __FILE__ == $0
  puts "Запуск сервера Nova Poshta Map..."
  puts "Відкрийте http://localhost:4567 у браузері"
  NovaPoshtaMapApp.run!
end
```

