        <div class="search-form">
            <input type="text" id="address" placeholder="Введіть адресу (наприклад, Київ, Хрещатик 1)" value="Київ, Хрещатик 1">
            <input type="number" id="radius" placeholder="Радіус пошуку (км)" value="5" min="1" max="50">
            <button onclick="findPostomaty()">Знайти поштомати</button>
        </div>

