    <script>
        let map = L.map('map').setView([50.4501, 30.5234], 12);
        let markers = [];

        // Додаємо карту
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '© OpenStreetMap contributors'
        }).addTo(map);

        async function findPostomaty() {
            const address = document.getElementById('address').value;
            const radius = document.getElementById('radius').value;

            if (!address) {
                alert('Будь ласка, введіть адресу');
                return;
            }

            try {
                const response = await fetch('/find-postomaty', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded',
                    },
                    body: `address=${encodeURIComponent(address)}&radius=${radius}`
                });

                const data = await response.json();

                // Очищаємо попередні маркери
                markers.forEach(marker => map.removeLayer(marker));
                markers = [];

                document.getElementById('postomatList').innerHTML = '';

                if (data.error) {
                    document.getElementById('postomatList').innerHTML = 
                        `<div class="error">${data.error}</div>`;
                    return;
                }

                // Центруємо карту на введеній адресі
                if (data.coordinates) {
                    map.setView([data.coordinates.lat, data.coordinates.lng], 14);

                    // Додаємо маркер для введеної адреси
                    const addressMarker = L.marker([data.coordinates.lat, data.coordinates.lng])
                        .addTo(map)
                        .bindPopup(`<b>Ваша адреса:</b><br>${data.coordinates.address}`);
                    markers.push(addressMarker);
                }

                // Додаємо маркери для поштоматів
                if (data.postomaty && data.postomaty.length > 0) {
                    data.postomaty.forEach(postomat => {
                        const marker = L.marker([postomat.lat, postomat.lng])
                            .addTo(map)
                            .bindPopup(`
                                <b>Поштомат №${postomat.number}</b><br>
                                ${postomat.address}<br>
                                Телефон: ${postomat.phone}<br>
                                Графік: ${postomat.schedule}
                            `);
                        markers.push(marker);
                    });

                    // Показуємо список поштоматів
                    let listHTML = '<h3>Знайдені поштомати:</h3>';
                    data.postomaty.forEach(postomat => {
                        listHTML += `
                            <div class="postomat-item">
                                <strong>№${postomat.number}: ${postomat.name}</strong><br>
                                Адреса: ${postomat.address}<br>
                                Телефон: ${postomat.phone}<br>
                                Графік: ${postomat.schedule}
                            </div>
                        `;
                    });
                    document.getElementById('postomatList').innerHTML = listHTML;
                } else {
                    document.getElementById('postomatList').innerHTML = 
                        '<div class="error">Поштоматів не знайдено у вказаному радіусі</div>';
                }

            } catch (error) {
                console.error('Помилка:', error);
                document.getElementById('postomatList').innerHTML = 
                    '<div class="error">Сталася помилка при пошуку</div>';
            }
        }

        // Автоматичний пошук при завантаженні сторінки
        document.addEventListener('DOMContentLoaded', findPostomaty);
    </script>
</body>
</html>
