## app.rb

```ruby
require 'sinatra'
require 'httparty'
require 'json'
require 'geocoder'
require 'sqlite3'
require 'active_record'

# Налаштування бази даних
ActiveRecord::Base.establish_connection(
  adapter: 'sqlite3',
  database: 'nova_poshta.db'
)

# Модель поштомату
class PostOffice < ActiveRecord::Base
  validates :address, presence: true
  validates :city, presence: true
  validates :latitude, presence: true
  validates :longitude, presence: true
end

# Створення таблиці для поштоматів
ActiveRecord::Schema.define do
  unless table_exists?(:post_offices)
    create_table :post_offices do |t|
      t.string :address
      t.string :city
      t.float :latitude
      t.float :longitude
      t.string :type
      t.timestamps
    end
  end
end

# Ініціалізація
configure do
  set :bind, '0.0.0.0'
  set :port, 4567
end

# Головна сторінка
get '/' do
  erb :index
end

# Пошук поштоматів
post '/find' do
  address = params[:address]
  return erb :error, locals: { message: "Будь ласка, введіть адресу" } if address.nil? || address.empty?

  begin
    # Отримання координат адреси
    results = Geocoder.search(address)
    if results.empty?
      return erb :error, locals: { message: "Не вдалося знайти адресу: #{address}" }
    end

    location = results.first
    lat = location.coordinates[0]
    lng = location.coordinates[1]

    # Отримання поштоматів Нової Пошти
    post_offices = get_nova_poshta_offices(lat, lng)

    # Розрахунок відстаней та сортування
    post_offices_with_distances = post_offices.map do |office|
      distance = calculate_distance(lat, lng, office[:latitude], office[:longitude])
      {
        address: office[:address],
        city: office[:city],
        latitude: office[:latitude],
        longitude: office[:longitude],
        distance: distance,
        type: office[:type]
      }
    end.sort_by { |o| o[:distance] }

    erb :results, locals: { 
      address: address,
      lat: lat,
      lng: lng,
      post_offices: post_offices_with_distances
    }
  rescue => e
    erb :error, locals: { message: "Помилка: #{e.message}" }
  end
end

# Отримання поштоматів Нової Пошти
def get_nova_poshta_offices(lat, lng)
  # У цьому прикладі ми використовуємо симуляцію даних,
  # оскільки реальний API Nova Poshta вимагає авторизації
  # Імітація даних для демонстрації

  [
    {
      address: "Вулиця Хрещатик, 1",
      city: "Київ",
      latitude: 50.4501,
      longitude: 30.5234,
      type: "Поштомат"
    },
    {
      address: "Вулиця Лесі Українки, 15",
      city: "Київ",
      latitude: 50.4427,
      longitude: 30.5317,
      type: "Поштомат"
    },
    {
      address: "Вулиця Різницька, 25",
      city: "Київ",
      latitude: 50.4571,
      longitude: 30.4522,
      type: "Поштомат"
    },
    {
      address: "Вулиця Свободи, 30",
      city: "Київ",
      latitude: 50.4357,
      longitude: 30.5418,
      type: "Поштомат"
    },
    {
      address: "Вулиця Михайла Грушевського, 10",
      city: "Київ",
      latitude: 50.4605,
      longitude: 30.5202,
      type: "Поштомат"
    }
  ]
end

# Розрахунок відстані між двома точками
def calculate_distance(lat1, lng1, lat2, lng2)
  # Використовуємо формулу Haversine для розрахунку відстані
  earth_radius = 6371 # km
  lat_diff = (lat2 - lat1).to_rad
  lng_diff = (lng2 - lng1).to_rad
  a = Math.sin(lat_diff / 2) * Math.sin(lat_diff / 2) +
      Math.cos(lat1.to_rad) * Math.cos(lat2.to_rad) *
      Math.sin(lng_diff / 2) * Math.sin(lng_diff / 2)
  c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  earth_radius * c # Відстань в кілометрах
end

# Допоміжний метод для конвертації градусів в радіани
class Numeric
  def to_rad
    self * Math::PI / 180
  end
end
