## Основна програма

```ruby
# app.rb
require 'sinatra'
require 'geocoder'
require 'httparty'
require 'json'

class NovaPoshtaMap < Sinatra::Base
  set :public_folder, File.dirname(__FILE__) + '/public'

  get '/' do
    erb :index
  end

  # API endpoint для пошуку поштоматів
  get '/api/postomaty' do
    content_type :json

    address = params[:address]

    if address.nil? || address.empty?
      return { error: "Адреса не вказана" }.to_json
    end

    begin
      # Геокодування адреси
      coordinates = geocode_address(address)

      if coordinates.nil?
        return { error: "Не вдалося знайти координати для адреси" }.to_json
      end

      # Отримання поштоматів Nova Poshta
      postomaty = get_nova_poshta_postomaty(coordinates[:lat], coordinates[:lng])

      {
        success: true,
        user_location: coordinates,
        postomaty: postomaty
      }.to_json

    rescue => e
      { error: "Помилка: #{e.message}" }.to_json
    end
  end

  private

  def geocode_address(address)
    results = Geocoder.search(address)

    if results.empty?
      return nil
    end

    {
      lat: results.first.latitude,
      lng: results.first.longitude,
      address: results.first.address
    }
  end

  def get_nova_poshta_postomaty(lat, lng, radius_km = 10)
    # Імітація даних поштоматів (у реальному застосунку використовувався б API Nova Poshta)
    # Тут можна використовувати офіційний API Nova Poshta, але для прикладу імітуємо дані

    mock_postomaty = [
      {
        id: 1,
        name: "Відділення №1",
        address: "вул. Хрещатик, 1, Київ",
        lat: lat + 0.01,
        lng: lng + 0.01,
        schedule: "Пн-Пт: 09:00-18:00, Сб: 10:00-16:00",
        phone: "+380441234567"
      },
      {
        id: 2,
        name: "Відділення №2", 
        address: "вул. Б. Хмельницького, 15, Київ",
        lat: lat - 0.015,
        lng: lng + 0.008,
        schedule: "Пн-Пт: 08:00-20:00, Сб-Нд: 10:00-18:00",
        phone: "+380441234568"
      },
      {
        id: 3,
        name: "Поштомат №3",
        address: "пр. Перемоги, 25, Київ", 
        lat: lat + 0.008,
        lng: lng - 0.012,
        schedule: "Цілодобово",
        phone: "+380441234569"
      }
    ]

    # Фільтрація поштоматів за радіусом
    filtered_postomaty = mock_postomaty.select do |postomat|
      distance = calculate_distance(lat, lng, postomat[:lat], postomat[:lng])
      distance <= radius_km
    end

    filtered_postomaty
  end

  def calculate_distance(lat1, lng1, lat2, lng2)
    # Проста формула гаверсинус для розрахунку відстані
    rad_per_deg = Math::PI / 180
    earth_radius_km = 6371

    dlat_rad = (lat2 - lat1) * rad_per_deg
    dlng_rad = (lng2 - lng1) * rad_per_deg

    lat1_rad = lat1 * rad_per_deg
    lat2_rad = lat2 * rad_per_deg

    a = Math.sin(dlat_rad/2)**2 + Math.cos(lat1_rad) * Math.cos(lat2_rad) * Math.sin(dlng_rad/2)**2
    c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))

    earth_radius_km * c
  end
end

if __FILE__ == $0
  NovaPoshtaMap.run!
end
```

