## JavaScript для клієнтської частини

```javascript
// public/script.js
let map;
let markers = [];
let userMarker;

function initMap() {
    // Ініціалізація карти з центром у Києві
    map = L.map('map').setView([50.4501, 30.5234], 12);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors'
    }).addTo(map);
}

function searchPostomaty() {
    const address = document.getElementById('addressInput').value.trim();

    if (!address) {
        alert('Будь ласка, введіть адресу');
        return;
    }

    showLoading();

    fetch(`/api/postomaty?address=${encodeURIComponent(address)}`)
        .then(response => response.json())
        .then(data => {
            if (data.error) {
                showError(data.error);
                return;
            }

            displayResults(data);
            displayOnMap(data);
        })
        .catch(error => {
            showError('Сталася помилка при пошуку: ' + error.message);
        });
}

function displayResults(data) {
    const resultsDiv = document.getElementById('results');
    resultsDiv.style.display = 'block';

    if (data.postomaty.length === 0) {
        resultsDiv.innerHTML = '<div class="error">Поштоматів поблизу не знайдено</div>';
        return;
    }

    let html = `<h2>Знайдено поштоматів: ${data.postomaty.length}</h2>`;
    html += '<ul class="postomat-list">';

    data.postomaty.forEach(postomat => {
        html += `
            <li class="postomat-item">
                <div class="postomat-name">${postomat.name}</div>
                <div class="postomat-address">Адреса: ${postomat.address}</div>
                <div class="postomat-schedule">Графік: ${postomat.schedule}</div>
                <div class="postomat-phone">Телефон: ${postomat.phone}</div>
            </li>
        `;
    });

    html += '</ul>';
    resultsDiv.innerHTML = html;
}

function displayOnMap(data) {
    // Очистити попередні маркери
    clearMarkers();

    // Додати маркер користувача
    userMarker = L.marker([data.user_location.lat, data.user_location.lng])
        .addTo(map)
        .bindPopup(`<b>Ваше місцезнаходження</b><br>${data.user_location.address}`)
        .openPopup();

    // Додати маркери поштоматів
    data.postomaty.forEach(postomat => {
        const marker = L.marker([postomat.lat, postomat.lng])
            .addTo(map)
            .bindPopup(`
                <b>${postomat.name}</b><br>
                Адреса: ${postomat.address}<br>
                Графік: ${postomat.schedule}<br>
                Телефон: ${postomat.phone}
            `);

        markers.push(marker);
    });

    // Масштабувати карту щоб показати всі маркери
    const group = new L.featureGroup([userMarker, ...markers]);
    map.fitBounds(group.getBounds().pad(0.1));
}

function clearMarkers() {
    markers.forEach(marker => map.removeLayer(marker));
    markers = [];

    if (userMarker) {
        map.removeLayer(userMarker);
        userMarker = null;
    }
}

function showLoading() {
    document.getElementById('results').innerHTML = '<div class="loading">Пошук поштоматів...</div>';
    document.getElementById('results').style.display = 'block';
}

function showError(message) {
    document.getElementById('results').innerHTML = `<div class="error">${message}</div>`;
    document.getElementById('results').style.display = 'block';
}

// Ініціалізація карти при завантаженні сторінки
document.addEventListener('DOMContentLoaded', initMap);

// Обробка натискання Enter у полі вводу
document.getElementById('addressInput').addEventListener('keypress', function(e) {
    if (e.key === 'Enter') {
        searchPostomaty();
    }
});
