require 'sinatra'
require 'httparty'
require 'json'

class PrivatBankCurrencyApp < Sinatra::Base
  set :views, File.dirname(__FILE__) + '/views'
  set :public_folder, File.dirname(__FILE__) + '/public'
  set :bind, '0.0.0.0'
  set :port, 4567

  API_URL = 'https://api.privatbank.ua/p24api/pubinfo?exchange&coursid=5'

  get '/' do
    @currencies = fetch_currency_rates
    @last_updated = Time.now.strftime("%H:%M:%S %d.%m.%Y")
    erb :index
  end

  get '/api/rates' do
    content_type :json
    fetch_currency_rates.to_json
  end

  private

  def fetch_currency_rates
    response = HTTParty.get(API_URL, timeout: 10)

    if response.success?
      JSON.parse(response.body)
    else
      # Повертаємо порожній масив у разі помилки
      []
    end
  rescue StandardError => e
    puts "Error fetching currency rates: #{e.message}"
    []
  end
end

PrivatBankCurrencyApp.run! if __FILE__ == $0
