    500 => 'п\'ятсот', 600 => 'шістсот', 700 => 'сімсот', 800 => 'вісімсот',
    900 => 'дев\'ятсот'
  }

  # Ukrainian currency forms
  HRYVNIA_FORMS = {
    singular: 'гривня',
    few: 'гривні',
    many: 'гривень'
  }

  KOPECKA_FORMS = {
    singular: 'копійка',
    few: 'копійки',
    many: 'копійок'
  }

  def self.to_words(amount)
    new(amount).to_words
  end

  def initialize(amount)
    @amount = amount.to_f.round(2)
    @hryvnias = @amount.to_i
    @kopecks = ((@amount - @hryvnias) * 100).round
  end

