## Implementation

### app.rb

```ruby
require 'sinatra'
require 'httparty'
require 'json'

class PrivatBankRates
  API_URL = 'https://api.privatbank.ua/p24api/pubinfo?json&exchange&coursid=5'

  def self.fetch_rates
    response = HTTParty.get(API_URL)

    if response.success?
      JSON.parse(response.body)
    else
      raise "Failed to fetch rates: #{response.code} - #{response.message}"
    end
  rescue StandardError => e
    puts "Error fetching rates: #{e.message}"
    []
  end
end

class CurrencyRatesApp < Sinatra::Base
  configure do
    set :protection, except: :frame_options
    set :show_exceptions, false
  end

  get '/' do
    @rates = PrivatBankRates.fetch_rates
    @last_updated = Time.now.strftime("%Y-%m-%d %H:%M:%S")
    erb :index
  end

  get '/api/rates' do
    content_type :json
    PrivatBankRates.fetch_rates.to_json
  end

  error do
    @error_message = env['sinatra.error']&.message || 'An unexpected error occurred'
    erb :error
  end

  not_found do
    @error_message = 'Page not found'
    erb :error
  end
end

# Run the app if this file is executed directly
CurrencyRatesApp.run! if __FILE__ == $0
