### app.rb

```ruby
require 'sinatra'
require 'sinatra/json'
require 'httparty'
require 'geocoder'
require 'json'
require 'dotenv/load'

# Configure Geocoder
Geocoder.configure(
  timeout: 5,
  units: :km
)

class NovaPoshtaAPI
  include HTTParty
  base_uri 'https://api.novaposhta.ua/v2.0/json'

  def initialize(api_key = ENV['NOVA_POSHTA_API_KEY'])
    @api_key = api_key
  end

  # Get poshtomats (parcel lockers) near given coordinates
  def get_poshtomats_near(lat, lng, radius_km = 5)
    # First, find the city based on coordinates
    city_ref = find_city_by_coordinates(lat, lng)
    return [] unless city_ref

    # Then get all poshtomats in that city
    get_poshtomats_in_city(city_ref)
  end

  private

  def find_city_by_coordinates(lat, lng)
    response = self.class.post('/Address/getCities', {
      body: {
        apiKey: @api_key,
        modelName: 'Address',
        calledMethod: 'getCities',
        methodProperties: {}
      }.to_json,
      headers: { 'Content-Type' => 'application/json' }
    })

    cities = JSON.parse(response.body)['data']

    # Find closest city to coordinates
    closest_city = cities.min_by do |city|
      city_lat = city['Latitude'].to_f
      city_lng = city['Longitude'].to_f
      distance = haversine_distance(lat, lng, city_lat, city_lng)
      distance
    end

    closest_city ? closest_city['Ref'] : nil
  end

  def get_poshtomats_in_city(city_ref)
    response = self.class.post('/Address/getWarehouses', {
      body: {
        apiKey: @api_key,
        modelName: 'AddressGeneral',
        calledMethod: 'getWarehouses',
        methodProperties: {
          CityRef: city_ref,
          TypeOfWarehouseRef: 'f9316480-5f2d-425d-bc2c-ac7cd29decf0' # Poshtomat type
        }
      }.to_json,
      headers: { 'Content-Type' => 'application/json' }
    })

    JSON.parse(response.body)['data'] || []
  end

  def haversine_distance(lat1, lon1, lat2, lon2)
    earth_radius_km = 6371.0

    # Convert degrees to radians
    lat1_rad = lat1 * Math::PI / 180
    lon1_rad = lon1 * Math::PI / 180
    lat2_rad = lat2 * Math::PI / 180
    lon2_rad = lon2 * Math::PI / 180

    # Haversine formula
    dlat = lat2_rad - lat1_rad
    dlon = lon2_rad - lon1_rad

    a = Math.sin(dlat/2)**2 + Math.cos(lat1_rad) * Math.cos(lat2_rad) * Math.sin(dlon/2)**2
    c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))

    earth_radius_km * c
  end
end

# Routes
get '/' do
  erb :index
end

post '/find_poshtomats' do
  content_type :json

  address = params[:address]
  radius = (params[:radius] || 5).to_f

  # Geocode the address
  results = Geocoder.search(address)

  if results.empty?
    return json({ error: 'Address not found' })
  end

  location = results.first
  lat = location.latitude
  lng = location.longitude

  # Get poshtomats from Nova Poshta API
  np_api = NovaPoshtaAPI.new
  poshtomats = np_api.get_poshtomats_near(lat, lng, radius)

  # Filter poshtomats by distance
  nearby_poshtomats = poshtomats.select do |poshtomat|
    poshtomat_lat = poshtomat['Latitude'].to_f
    poshtomat_lng = poshtomat['Longitude'].to_f

    distance = Geocoder::Calculations.distance_between(
      [lat, lng], 
      [poshtomat_lat, poshtomat_lng],
      units: :km
    )

    distance <= radius
  end

  # Format response
  response_data = {
    center: {
      lat: lat,
      lng: lng,
      address: location.address
    },
    poshtomats: nearby_poshtomats.map do |p|
      {
        id: p['Ref'],
        name: p['Description'],
        address: p['ShortAddress'],
        lat: p['Latitude'].to_f,
        lng: p['Longitude'].to_f,
        schedule: p['Schedule'] || '24/7',
        max_weight: p['TotalMaxWeightAllowed'],
        number: p['Number']
      }
    end
  }

  json response_data
end
```

